import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","frontmatter":{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","splitFrom":"life/personal/yijing/hexagrams-41-48.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","summary":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力","link":"/life/personal/yijing/hexagrams-41-48-part-01"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测","link":"/life/personal/yijing/hexagrams-41-48-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力","link":"/life/personal/yijing/hexagrams-41-48-part-01"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测","link":"/life/personal/yijing/hexagrams-41-48-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-41-48-part-02.md","filePath":"life/personal/yijing/hexagrams-41-48-part-02.md"}'),n={name:"life/personal/yijing/hexagrams-41-48-part-02.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-44-姤-相遇之际先辨关系至46-升-积累生长也须知止" tabindex="-1">六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止 <a class="header-anchor" href="#六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-44-姤-相遇之际先辨关系至46-升-积累生长也须知止" aria-label="Permalink to &quot;六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-41-48">返回分篇目录</a></p><p>本篇逐卦列出卦辞、六爻和大象。<strong>原文</strong>保留古字，<strong>白话概括</strong>为现代原创说明；解释主要参照王弼注、孔颖达疏《周易正义》。它们分别属于经文、传文与后世注释，不宜混成同一时代的一段话。卦符的六爻自下而上读，上下卦的自然象是解释线索，不能当作现代自然科学机制。</p><p>损益涉及付出与受益的方向，夬姤涉及决断与相遇，萃升涉及聚集与生长，困井则把个人困顿引向持续供养。读“吉凶”时保留古代占筮语境；现实选择仍需事实、资源与具体责任。</p><h2 id="gua-44" tabindex="-1">44 姤：相遇之际先辨关系 <a class="header-anchor" href="#gua-44" aria-label="Permalink to &quot;44 姤：相遇之际先辨关系 {#gua-44}&quot;">​</a></h2><p><strong>卦符：䷫｜上卦乾 ☰（天），下卦巽 ☴（风）。</strong>“姤”读 gòu，义为遇。一阴在下遇五阳，是古注解释卦名的入口。</p><p><strong>卦辞原文：</strong></p><blockquote><p>姤：女壯，勿用取女。</p></blockquote><p><strong>白话概括：</strong> 卦辞以强势女子的婚姻占问表达警戒，“取”通娶。《正义》将一阴五阳对应一女遇五男，解释带有鲜明的古代性别规范。应如实认识这个背景，不把它变成评价独立女性的标准；《彖传》又肯定天地相遇、万物显现，说明“遇”本身并非一概有害。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>系于金柅，貞吉，有攸往，見凶，羸豕，孚，蹢躅。</td><td>以金属止车器和躁动猪的画面说明初生力量难制。“柅”器物说法有别，断句也有异，宜保留不确定性。</td></tr><tr><td>九二</td><td>包有魚，无咎，不利賓。</td><td>包中有鱼，可维持自身关系却不宜扩及宾客；古注着重关系归属，不是关于宴客食材的禁忌。</td></tr><tr><td>九三</td><td>臀无膚，其行次且，厲，无大咎。</td><td>想接近却进退不便，危险中仍可避免更大过错；与夬九四同用受伤和迟行的画面。</td></tr><tr><td>九四</td><td>包无魚，起凶。</td><td>原有联系丧失，行动便有风险；《小象》解释为“远民”，提示上位者疏离下方的代价。</td></tr><tr><td>九五</td><td>以杞包瓜，含章，有隕自天。</td><td>以杞护瓜、含藏文采，古注借高大包护卑小解释；植物、包裹与“陨”的训释复杂，不宜作精密占验。</td></tr><tr><td>上九</td><td>姤其角，吝，无咎。</td><td>相遇却以尖角相接，隔碍而可惜；处在极端位置不易相合，不意味着永远没有关系可能。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>天下有風，姤；后以施命誥四方。</p></blockquote><p><strong>大象解释：</strong> 风行天下，引出统治者向各方发布命令。“后”指君主；可见大象把卦义转向广泛传达，已超出婚姻题材。</p><p><strong>整体读法与误区：</strong> 可把本卦分为三个层次：经文的婚姻、器物意象，古注的阴阳政治类比，今天对接触和边界的反思。现代阅读可以问相遇是否平等、承诺是否清楚、依赖是否过早，但这些是新问题。把姤直接定成“桃花卦”，或据一阴五阳推断某人的性行为，既越过文本证据，也忽略《彖传》的广义相遇。</p><p><strong>经传对读：</strong> 九二有鱼，九四无鱼，相同容器意象中内容不同；九三仍能免大咎，上九则处在相遇的尽头。这些差别说明“遇”包含获得联系、失去联系和难以相合。再与大象向四方传命对读，可看到古人如何从局部婚姻与食物图景扩大到政治沟通，读者应把这个解释步骤明确标出来。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4" target="_blank" rel="noopener noreferrer">《周易·姤》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E5%A7%A4" target="_blank" rel="noopener noreferrer">《周易正义》卷五·姤</a>。</p><h2 id="gua-45" tabindex="-1">45 萃：聚集须有共同依据 <a class="header-anchor" href="#gua-45" aria-label="Permalink to &quot;45 萃：聚集须有共同依据 {#gua-45}&quot;">​</a></h2><p><strong>卦符：䷬｜上卦兑 ☱（泽），下卦坤 ☷（地）。</strong>“萃”读 cuì，意为聚集。泽水聚在地上，既可滋养，也需要防范汇聚后的风险。</p><p><strong>卦辞原文（从《正义》本）：</strong></p><blockquote><p>萃：亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。</p></blockquote><p><strong>白话概括：</strong> 人群聚集，王到宗庙行礼，需要适当的主持者与正当共同目标。《周易》独立电子页开头未列第一个“亨”，《正义》有之，此处明示底本差别。宗庙和大牲属于古代聚族、祭享与政治秩序，不只是庆祝宴席。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>有孚不終，乃亂乃萃，若號一握為笑，勿恤，往无咎。</td><td>信任不能坚持，聚散便混乱；由呼号转笑的句子断解不一，可把握其情绪与关系不稳的处境。</td></tr><tr><td>六二</td><td>引吉，无咎，孚乃利用禴。</td><td>受到牵引而相聚，以诚信行简约祭礼亦可；“禴”是祭名，不把聚集只建立在礼物厚薄上。</td></tr><tr><td>六三</td><td>萃如，嗟如，无攸利，往无咎，小吝。</td><td>想聚却叹息，眼下无利；主动寻求联系可少过，仍可能有些尴尬，不必假装聚会总是融洽。</td></tr><tr><td>九四</td><td>大吉，无咎。</td><td>位不完全相当，须有足够好的聚合效果才得无咎；“大吉”在古注中含有严格条件。</td></tr><tr><td>九五</td><td>萃有位，无咎。匪孚，元永貞，悔亡。</td><td>有职位并不等于已获信任；需要长久正当的行为，才能弥补疑虑。</td></tr><tr><td>上六</td><td>齎咨涕洟，无咎。</td><td>叹息流泪，显出身处聚集之末仍不安；“齎咨”另见“齎資”，此依《小象》与古注常见写法。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤上于地，萃；君子以除戎器，戒不虞。</p></blockquote><p><strong>大象解释：</strong> 整治器备，防范未料的事。“除”在这里是修治整备，并非把武器全部清除；大象认为聚集也伴随秩序和防备问题。</p><p><strong>整体读法与误区：</strong>《正义》既反对一味顺从取悦，也反对刚亢强制，强调居中相应。现代可用来审视社群和会议：为何相聚，谁尚未被听见，名义负责人是否有真实信任，聚集规模是否超过组织能力。不能因为人数多就宣布事情正当，也不能把大象的军备背景直接换成今天人际关系中的戒备心。</p><p><strong>经传对读：</strong> 卦辞说用大牲，六二却说诚信可用简约禴祭；聚集的规模和祭品厚薄不是同一尺度。初六的号笑、六三的叹息、上六的流泪，也说明身在人群中不代表已经获得归属。与九五“匪孚”连读，可以把有组织、有职位、有礼仪与真正的相互信任逐层区分。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83" target="_blank" rel="noopener noreferrer">《周易·萃》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E8%90%83" target="_blank" rel="noopener noreferrer">《周易正义》卷五·萃</a>。</p><h2 id="gua-46" tabindex="-1">46 升：积累生长也须知止 <a class="header-anchor" href="#gua-46" aria-label="Permalink to &quot;46 升：积累生长也须知止 {#gua-46}&quot;">​</a></h2><p><strong>卦符：䷭｜上卦坤 ☷（地），下卦巽 ☴（木）。</strong> 地中木生，从细小长为高大，是升卦最清楚的自然比喻。</p><p><strong>卦辞原文：</strong></p><blockquote><p>升：元亨，用見大人，勿恤，南征吉。</p></blockquote><p><strong>白话概括：</strong> 上升之道通达，寻求有德有能者相助，可以减轻忧虑；“南征”在《正义》中解释为趋向明处。古注同时指出，纯柔不能自升，刚亢又无人愿从，需要合时与相应；不能只靠服从换取上升。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>允升，大吉。</td><td>允当而升，与上方同心形成支持；“允”有诚信、允当等训释，古注此处偏重当其时。</td></tr><tr><td>九二</td><td>孚乃利用禴，无咎。</td><td>以信实为先，祭礼虽简也可；与萃六二相照，应重共同诚意而不只追求形式规模。</td></tr><tr><td>九三</td><td>升虛邑。</td><td>进入空虚无阻的邑，前行较为容易；一句描述当前通路，尚未证明以后没有风险。</td></tr><tr><td>六四</td><td>王用享于岐山，吉无咎。</td><td>王在岐山祭享，古注强调顺事；“享／亨”有异文，应放回周人礼制与地理记忆理解。</td></tr><tr><td>六五</td><td>貞吉，升階。</td><td>守正而一级一级登阶，进步有次序；台阶的比喻强调承接，不是固定的升职时间表。</td></tr><tr><td>上六</td><td>冥升，利于不息之貞。</td><td>昏昧地只知上升会耗损；把不断追求转向不息的正当修养，才是古注试图保留的可取方向。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>地中生木，升；君子以順德，積小以高大。</p></blockquote><p><strong>大象解释：</strong> 木从微小积累而大，人的德行也由日常小事形成。“积小”说明过程，不保证任何重复都会产生有益结果；积累的内容仍须检验。</p><p><strong>整体读法与误区：</strong> 升与晋都谈进，晋更突出光明显现和受接见，升更突出由下而上的渐积。读到上六，应回头检查增长是否成为唯一目标：耗尽睡眠、关系或生活资源的“冥升”，并不因努力就自动合理。现实学习或技艺训练可以借“升阶”建立可检验的小步骤，同时允许调整和休息，不把古文改造成无限进步的压力。</p><p><strong>经传对读：</strong> 初六重合志，九二重信实，六五写阶梯，上六则警惕昏昧上升。这里的条件来自人与人之间的支持，也来自步序本身。大象用树木的生长补充时间因素，不能由此推出人只需被动等待。晋的厚赏、升的渐积与大壮的强力，正可以比较三种不同的进取意象及各自受到的限制。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87" target="_blank" rel="noopener noreferrer">《周易·升》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E5%8D%87" target="_blank" rel="noopener noreferrer">《周易正义》卷五·升</a>。</p>',43)])])}const u=r(n,[["render",d]]);export{c as __pageData,u as default};
